IF NOT EXISTS (SELECT * FROM sys.foreign_keys WHERE object_id = OBJECT_ID(N'[dbo].[FK_EnvironmentTemplate_DatabaseServer]') AND parent_object_id = OBJECT_ID(N'[dbo].[EnvironmentTemplate]'))
begin
	ALTER TABLE [dbo].[EnvironmentTemplate]  WITH CHECK ADD  CONSTRAINT [FK_EnvironmentTemplate_DatabaseServer] FOREIGN KEY([DatabaseServerID]) REFERENCES [dbo].[DatabaseServer] ([ID]);
	ALTER TABLE [dbo].[EnvironmentTemplate] CHECK CONSTRAINT [FK_EnvironmentTemplate_DatabaseServer];
end
